  const baseKey = keyOk(originalKey)
    ? originalKey
    : slug(issue.title || `issue-${index + 1}`).slice(0, 40);
  let key = baseKey;
  let suffix = 1;
  while (usedKeys.has(key)) {
    key = `${baseKey}-${++suffix}`;
  }
  usedKeys.add(key);
  keyMap.set(originalKey, key);
  keyMap.set(issue.key, key);

