    seenTitles.add(semanticTitle);

    const internal = issue.requirementKind === "internalWorkflowRequirement";
    if (!internal && issue.requirementKind !== "sourceRequirement")
      addError(
        "INVALID_REQUIREMENT_KIND",
        `${where}: requirementKind inválido`,
