  if (Array.isArray(data.resumeKeys) && data.resumeKeys.length) {
    const expected = [...new Set(data.resumeKeys)].sort().join(",");
    const actual = [
      ...new Set(
        issues
          .filter((issue) => issue.requirementKind === "sourceRequirement")
          .map((issue) => issue.key),
      ),
    ]
      .sort()
      .join(",");
    if (actual !== expected)
      addError(
        "RESUME_KEYS_MISMATCH",
        `keys funcionales esperadas ${expected}; recibidas ${actual}`,
      );
  }
}

// A single transition table owns routing; IF nodes only inspect nextState.
let valid = errors.length === 0 && data.parseStatus === 'valid' && data.schemaStatus === 'valid';
const hasParseIssue = Boolean(data.parseError);
let internalDetected = errors.some((error) => error.kind === "validator");
if (data.schemaStatus === "valid" && data.errorType === "SCHEMA_ERROR" && !hasParseIssue) {
  internalDetected = true;
  addError(
    "VALIDATOR_INTERNAL",
    "Inconsistencia interna: schemaStatus=valid no puede producir SCHEMA_ERROR",
    false,
    { kind: "validator" },
  );
  valid = false;
}
const provenanceDetected = errors.some((error) => error.kind === "provenance");
const groundingDetected = errors.some((error) => error.kind === "grounding");
const dependencyDetected = errors.some((error) => error.kind === "dependency");
const semanticDetected = errors.some((error) => !error.kind);

let errorType;
if (hasParseIssue) errorType = data.errorType || "SCHEMA_ERROR";
else if (internalDetected) errorType = "VALIDATOR_INTERNAL_ERROR";
else if (provenanceDetected) errorType = "PROVENANCE_ERROR";
else if (groundingDetected) errorType = "GROUNDING_ERROR";
else if (dependencyDetected) errorType = "DEPENDENCY_ERROR";
else if (semanticDetected) errorType = "SEMANTIC_ERROR";
else errorType = valid ? "VALID" : "SCHEMA_ERROR";

const statuses = {
  transportStatus: data.normalizedResponse?.transportStatus || "not_attempted",
  providerStatus: data.normalizedResponse?.providerStatus || "not_attempted",
  parseStatus: data.parseStatus || "not_attempted",
  schemaStatus: data.schemaStatus || "not_attempted",
  groundingStatus:
    provenanceDetected || groundingDetected
      ? "invalid"
      : hasParseIssue ? "not_attempted" : "valid",
  semanticStatus: semanticDetected
    ? "invalid"
    : hasParseIssue ? "not_attempted" : "valid",
  dependencyStatus: dependencyDetected
    ? "invalid"
    : hasParseIssue ? "not_attempted" : "valid",
  finalPlanStatus: valid ? "accepted" : "rejected",
};

const failureReason = valid ? null : {
  errorType,
  provider: data.llmAttempt?.provider || null,
  model: data.llmAttempt?.model || null,
  httpStatus: data.normalizedResponse?.httpStatus ?? null,
  message: data.normalizedResponse?.error || errors.map((error) => error.message).join("; "),
  ...(["PARSE_ERROR", "SCHEMA_ERROR"].includes(errorType)
    ? { validationErrors: errors.map((error) => error.message) } : {}),
  ...(["GROUNDING_ERROR", "PROVENANCE_ERROR"].includes(errorType)
    ? {
        validationErrors: errors.map((error) => error.message),
        groundingErrors: errors
          .filter((error) => ["grounding", "provenance"].includes(error.kind))
          .map((error) => ({
            issueKey: error.issueKey,
            detail: error.detail,
            reason: error.reason,
            sourceId: error.sourceId || null,
          })),
      }
    : {}),
  ...(errorType === "VALIDATOR_INTERNAL_ERROR"
    ? {
        message: "Provenance resoluble ignorado por el validator",
        details: errors
          .filter((error) => error.kind === "validator")
          .map((error) => ({
            issueKey: error.issueKey,
            detail: error.detail,
            matchedSourceId: error.sourceId || null,
            message: error.message,
          })),
      }
    : {}),
};
const stage = data.llmAttempt?.stage || 'gemini';
const repairUsed = Boolean(data.repairUsed);
const fallbackUsed = ['qwen', 'glm'].includes(stage);
const REPAIRABLE = new Set([
  'PARSE_ERROR', 'SCHEMA_ERROR', 'GROUNDING_ERROR', 'PROVENANCE_ERROR',
  'SEMANTIC_ERROR', 'DEPENDENCY_ERROR',
]);
const transitions = { gemini_repair: 'QWEN_REQUEST', qwen: 'GLM_REQUEST', glm: 'FAIL_CLOSED' };
let nextState;
if (valid) nextState = 'PLAN_VALID';
else if (errorType === 'VALIDATOR_INTERNAL_ERROR') nextState = 'FAIL_VALIDATOR';
else if (stage === 'gemini') nextState = !repairUsed && REPAIRABLE.has(errorType)
  ? 'GEMINI_REPAIR_REQUEST' : 'QWEN_REQUEST';
else nextState = transitions[stage];
if (!nextState) throw new Error('AI_STATE_INVALID: transición desconocida');
const normalizedResponse = {
  ...(data.normalizedResponse || {}),
  success: valid,
  error: failureReason?.message || null,
  errorType,
  failureReason,
  validationStatus: valid ? 'valid' : 'invalid',
  ...statuses,
  groundingReport,
};
const stateHistory = [...(data.stateHistory || [])];
if (!hasParseIssue && data.schemaStatus === 'valid')
  stateHistory.push(`${String(stage).toUpperCase()}_GROUNDING_VALIDATE`);
if (['PLAN_VALID', 'FAIL_CLOSED', 'FAIL_VALIDATOR'].includes(nextState))
  stateHistory.push(nextState);
const observation = {
  provider: normalizedResponse.provider || data.llmAttempt?.provider || null,
  model: normalizedResponse.model || data.llmAttempt?.model || null,
  stage: stage === 'gemini' ? 'initial' : stage === 'gemini_repair' ? 'repair' : stage,
  httpStatus: normalizedResponse.httpStatus ?? null,
  result: errorType.toLowerCase(), errorType, success: valid,
  ...statuses,
  validationStatus: normalizedResponse.validationStatus,
  repairUsed, fallbackUsed, failureReason,
  providerError: normalizedResponse.providerError || null,
  durationMs: normalizedResponse.durationMs ?? null,
  identifierNormalizations: data.identifierNormalizations || [],
  groundingReport,
};
const aiObservability = [...(data.aiObservability || []), observation];
const aiExecution = {
  requestedProvider: 'gemini',
  resolvedProvider: valid ? observation.provider : null,
  resolvedModel: valid ? observation.model : null,
  repairUsed, fallbackUsed,
};
return [{ json: {
  ...data, valid, retryable: false, errorType, failureReason, nextState,
  llmState: nextState, stateHistory, repairUsed, fallbackUsed,
  validationErrors: errors, normalizedResponse, aiObservability, aiExecution,
  ...statuses, groundingReport,
  mode: 'dry-run', automationMode: 'dry-run', mutationsPerformed: false,
} }];

const data = $json;
if (!data.plan || !Array.isArray(data.plan.issues))
  throw new Error("Plan rechazado: data.plan.issues no existe.");

const plan = JSON.parse(JSON.stringify(data.plan));
const issues = plan.issues;
const byKey = new Map(issues.map((issue) => [issue.key, issue]));
const indegree = new Map(issues.map((issue) => [issue.key, 0]));
const outgoing = new Map(issues.map((issue) => [issue.key, []]));
for (const issue of issues) {
  if (!Array.isArray(issue.dependsOn)) issue.dependsOn = [];
  for (const dependency of issue.dependsOn) {
    if (!byKey.has(dependency))
      throw new Error(
        `Plan rechazado: ${issue.key} depende de "${dependency}" inexistente.`,
      );
    indegree.set(issue.key, indegree.get(issue.key) + 1);
    outgoing.get(dependency).push(issue.key);
  }
}
const queue = issues
  .filter((issue) => indegree.get(issue.key) === 0)
  .map((issue) => issue.key);
const ordered = [];
while (queue.length) {
  const key = queue.shift();
  ordered.push(byKey.get(key));
  for (const next of outgoing.get(key)) {
    indegree.set(next, indegree.get(next) - 1);
    if (indegree.get(next) === 0) queue.push(next);
  }
}
if (ordered.length !== issues.length)
  throw new Error("Plan rechazado: existen dependencias circulares.");

const members = ["Draggodeidad", "JulianDele", "osbaldoXxC"];
const loads = Object.fromEntries(
  members.map((member) => [
    member,
    {
      functional: 0,
      technical: 0,
      operational: 0,
      issueCount: 0,
    },
  ]),
);
const technicalCategories = new Set([
  "implementation",
  "integration",
  "infrastructure",
]);
const osbaldoSafeCategories = new Set([
  "testing",
  "documentation",
  "evidence",
  "validation",
  "ui",
  "implementation",
]);
const riskyNature =
  /arquitectura|autenticaci[oó]n|seguridad|infraestructura|ci\/cd|persistencia|sincronizaci[oó]n|concurrencia|backend cr[ií]tico|refactor estructural/i;
const isTechnical = (issue) =>
  Boolean(
    issue.requiresCoding ||
    issue.requiresRepositoryKnowledge ||
    technicalCategories.has(issue.category),
  );
const safeForOsbaldo = (issue) =>
  issue.difficulty !== "hard" &&
  issue.risk === "low" &&
  osbaldoSafeCategories.has(issue.category) &&
  !(issue.category === "implementation" && issue.requiresRepositoryKnowledge) &&
  !(
    issue.requiresCoding &&
    technicalCategories.has(issue.category) &&
    riskyNature.test(`${issue.title} ${issue.body}`)
  );
const choose = (candidates, score, preference) =>
  [...candidates].sort((a, b) => {
    const difference = score(a) - score(b);
    return difference || preference.indexOf(a) - preference.indexOf(b);
  })[0];

for (const issue of ordered) {
  const operational = issue.requirementKind === "internalWorkflowRequirement";
  if (operational) {
    issue.assignee = "Draggodeidad";
    issue.functionalWeight = 0;
    issue.operationalWeight = Number(issue.operationalWeight || 1);
    loads.Draggodeidad.operational += issue.operationalWeight;
    loads.Draggodeidad.issueCount += 1;
    continue;
  }

  const weight = Number(issue.estimatedWeight || 1);
  const technical = isTechnical(issue);
  let candidates;
  let preference;
  let score;
  if (issue.difficulty === "hard") {
    candidates = ["Draggodeidad", "JulianDele"];
    preference = ["Draggodeidad", "JulianDele"];
    score = (member) => loads[member].technical * 10 + loads[member].functional;
  } else if (issue.difficulty === "medium") {
    const skilled = ["JulianDele", "Draggodeidad"];
    const leastSkilledLoad = Math.min(
      ...skilled.map((member) => loads[member].functional),
    );
    candidates =
      safeForOsbaldo(issue) &&
      loads.osbaldoXxC.functional + weight < leastSkilledLoad
        ? [...skilled, "osbaldoXxC"]
        : skilled;
    preference = ["JulianDele", "Draggodeidad", "osbaldoXxC"];
    score = (member) =>
      loads[member].functional + (technical ? loads[member].technical : 0);
  } else {
    const eligible = safeForOsbaldo(issue)
      ? members
      : ["Draggodeidad", "JulianDele"];
    const leastOther = Math.min(
      loads.Draggodeidad.functional,
      loads.JulianDele.functional,
    );
    if (
      eligible.includes("osbaldoXxC") &&
      loads.osbaldoXxC.functional <= leastOther + 2
    ) {
      candidates = ["osbaldoXxC"];
    } else {
      candidates = eligible;
    }
    preference = ["osbaldoXxC", "JulianDele", "Draggodeidad"];
    score = (member) => loads[member].functional;
  }

  issue.assignee = choose(candidates, score, preference);
  issue.functionalWeight = weight;
  issue.operationalWeight = 0;
  loads[issue.assignee].functional += weight;
  if (technical) loads[issue.assignee].technical += weight;
  loads[issue.assignee].issueCount += 1;
}

const unsafeOsbaldo = ordered.filter(
  (issue) =>
    issue.assignee === "osbaldoXxC" &&
    issue.requirementKind === "sourceRequirement" &&
    !safeForOsbaldo(issue),
);
if (unsafeOsbaldo.length)
  throw new Error(
    `Plan rechazado: asignación insegura para osbaldoXxC: ${unsafeOsbaldo.map((issue) => issue.key).join(", ")}`,
  );
const hardOwners = new Set(
  ordered
    .filter(
      (issue) =>
        issue.difficulty === "hard" &&
        issue.requirementKind === "sourceRequirement",
    )
    .map((issue) => issue.assignee),
);
if (hardOwners.has("osbaldoXxC"))
  throw new Error("Plan rechazado: una tarea hard fue asignada a osbaldoXxC.");

const planKeys = ordered.map((issue) => issue.key);
const desiredLabels = [
  ...new Set([
    data.course,
    `week-${data.weekPadded}`,
    ...ordered.flatMap((issue) => [
      `type:${issue.type}`,
      `priority:${issue.priority}`,
    ]),
  ]),
].filter(Boolean);
const existingLabels = new Set(data.repoContext?.labels || []);

return [
  {
    json: {
      ...data,
      plan: { ...plan, issues: ordered },
      planKeys,
      desiredLabels,
      missingLabels: desiredLabels.filter(
        (label) => !existingLabels.has(label),
      ),
      bootstrapKey: data.starter?.found ? "foundation" : null,
      assignmentPolicy: {
        strategy: "capability-aware-weighted-load",
        difficultyWeights: { easy: 1, medium: 2, hard: 3 },
        operationalExcludedFromFunctionalBalance: true,
        loads,
      },
    },
  },
];

const colors = {
  DMI: '1D76DB', PWA: '5319E7',
  feature: '0E8A16', test: 'BFD4F2', docs: '0075CA', devops: 'FBCA04', evidence: 'C5DEF5',
  high: 'D93F0B', medium: 'FBCA04', low: '0E8A16',
};
const descriptions = {
  DMI: 'Materia DMI', PWA: 'Materia PWA',
  feature: 'Implementación de funcionalidad', test: 'Pruebas y calidad', docs: 'Documentación', devops: 'Infraestructura y automatización', evidence: 'Evidencia requerida',
  high: 'Prioridad alta', medium: 'Prioridad media', low: 'Prioridad baja',
};
const base = $json;
return base.missingLabels.map((name) => {
  const suffix = name.split(':')[1] || name;
  const isWeek = name.startsWith('week-');
  return {
    json: {
      runData: base,
      labelPayload: {
        name,
        color: isWeek ? 'D4C5F9' : (colors[suffix] || colors[name] || 'EDEDED'),
        description: isWeek ? `Semana ${name.slice(5)}` : (descriptions[suffix] || descriptions[name] || 'Creada por automatización Classroom'),
      },
    },
  };
});

const data = $json;
const metadata = (body, key) => {
  const match = String(body || '').match(new RegExp(`<!--\\s*${key}:([^>]+?)\\s*-->`, 'i'));
  return match ? match[1].trim() : null;
};
const runKey = `${data.courseId}:${data.courseWorkId}`;
const staticData = $getWorkflowStaticData('global');
staticData.classroomRuns ||= {};
const numbers = {};
for (const issue of data.existingAutomationIssues || []) {
  const key = metadata(issue.body, 'issue-key');
  if (key) numbers[key] = issue.number;
}
staticData.classroomRuns[runKey] = {
  courseId: data.courseId,
  courseWorkId: data.courseWorkId,
  course: data.course,
  week: data.weekPadded,
  repository: data.repository,
  planKeys: data.planKeys,
  numbers,
  updatedAt: new Date().toISOString(),
};

return data.plan.issues.map((issue, index) => ({
  json: {
    runKey,
    index,
    repository: data.repository,
    courseId: data.courseId,
    courseWorkId: data.courseWorkId,
    updateTime: data.updateTime,
    starterName: data.starter?.name || null,
    course: data.course,
    weekPadded: data.weekPadded,
    planKeys: data.planKeys,
    issue,
  },
}));

const item = $json;
const staticData = $getWorkflowStaticData('global');
const state = staticData.classroomRuns?.[item.runKey];
if (!state) throw new Error(`No existe estado de ejecución para ${item.runKey}`);
const issue = item.issue;
const existingNumber = state.numbers[issue.key];
const missingDependencies = issue.dependsOn.filter((key) => !state.numbers[key]);
if (missingDependencies.length) throw new Error(`No se resolvieron dependencias de ${issue.key}: ${missingDependencies.join(', ')}`);
const dependencyLines = issue.dependsOn.length
  ? issue.dependsOn.map((key) => `- #${state.numbers[key]} (${key})`).join('\n')
  : '- Ninguna.';
let body = String(issue.body).replace(
  /## Dependencias[\s\S]*?(?=\n## Evidencia individual)/,
  `## Dependencias\n\n${dependencyLines}\n`,
);
body = `${body.trim()}\n\n<!-- automation:classroom -->\n<!-- classroom-course-id:${item.courseId} -->\n<!-- classroom-coursework-id:${item.courseWorkId} -->\n<!-- classroom-update-time:${item.updateTime} -->\n<!-- course:${item.course} -->\n<!-- week:${item.weekPadded} -->\n<!-- issue-key:${issue.key} -->\n<!-- starter:${item.starterName || 'none'} -->\n<!-- plan-keys:${item.planKeys.join(',')} -->`;

return [{
  json: {
    ...item,
    skipCreate: Boolean(existingNumber),
    issueNumber: existingNumber || null,
    issuePayload: {
      title: issue.title,
      body,
      assignees: [issue.assignee],
      labels: [item.course, `week-${item.weekPadded}`, `type:${issue.type}`, `priority:${issue.priority}`],
    },
  },
}];

const source = $('Resolve Dependencies').item.json;
const response = $json.body ?? $json;
const issues = Array.isArray(response) ? response : [];
const metadata = (body, key) => {
  const match = String(body || '').match(new RegExp(`<!--\\s*${key}:([^>]+?)\\s*-->`, 'i'));
  return match ? match[1].trim() : null;
};
const existing = issues.find((issue) =>
  metadata(issue.body, 'classroom-course-id') === source.courseId &&
  metadata(issue.body, 'classroom-coursework-id') === source.courseWorkId &&
  metadata(issue.body, 'issue-key') === source.issue.key
);
if (existing) {
  const staticData = $getWorkflowStaticData('global');
  staticData.classroomRuns[source.runKey].numbers[source.issue.key] = existing.number;
}
return [{
  json: {
    ...source,
    skipCreate: Boolean(existing || source.skipCreate),
    issueNumber: existing?.number || source.issueNumber || null,
  },
}];

const source = $('Apply Issue Recheck').item.json;
const response = $json.body ?? $json;
const number = response.number || source.issueNumber;
if (!number) throw new Error(`No se pudo reconciliar la Issue existente ${source.issue.key}`);
const staticData = $getWorkflowStaticData('global');
const state = staticData.classroomRuns[source.runKey];
state.numbers[source.issue.key] = number;
state.updatedAt = new Date().toISOString();
return [{ json: { runKey: source.runKey, key: source.issue.key, number, created: false, reconciled: true } }];

const source = $('Resolve Dependencies').item.json;
const response = $json.body ?? $json;
if (!response.number) throw new Error(`GitHub no devolvió número para ${source.issue.key}`);
const staticData = $getWorkflowStaticData('global');
const state = staticData.classroomRuns[source.runKey];
state.numbers[source.issue.key] = response.number;
state.updatedAt = new Date().toISOString();
return [{ json: { runKey: source.runKey, key: source.issue.key, number: response.number, created: true } }];

const planData = $('Plan and Topological Sort').item.json;
const response = $json.body ?? $json;
const issues = Array.isArray(response) ? response : [];
const metadata = (body, key) => {
  const match = String(body || '').match(new RegExp(`<!--\\s*${key}:([^>]+?)\\s*-->`, 'i'));
  return match ? match[1].trim() : null;
};
const matching = issues.filter((issue) =>
  metadata(issue.body, 'classroom-course-id') === planData.courseId &&
  metadata(issue.body, 'classroom-coursework-id') === planData.courseWorkId &&
  metadata(issue.body, 'course') === planData.course &&
  metadata(issue.body, 'week') === planData.weekPadded
);
const byKey = Object.fromEntries(matching.map((issue) => [metadata(issue.body, 'issue-key'), issue]));
const missing = planData.planKeys.filter((key) => !byKey[key]);
if (missing.length) throw new Error(`Verificación falló; faltan Issues: ${missing.join(', ')}.`);
const configurationErrors = [];
for (const expected of planData.plan.issues) {
  const actual = byKey[expected.key];
  const assignees = (actual.assignees || []).map((assignee) => assignee.login);
  const labels = (actual.labels || []).map((label) => label.name || label);
  const expectedLabels = [planData.course, `week-${planData.weekPadded}`, `type:${expected.type}`, `priority:${expected.priority}`];
  if (!assignees.includes(expected.assignee)) configurationErrors.push(`${expected.key}: falta assignee ${expected.assignee}`);
  for (const label of expectedLabels) if (!labels.includes(label)) configurationErrors.push(`${expected.key}: falta label ${label}`);
  if (!metadata(actual.body, 'plan-keys')) configurationErrors.push(`${expected.key}: falta plan-keys`);
}
if (configurationErrors.length) throw new Error(`Verificación de Issues falló: ${configurationErrors.join('; ')}.`);
const assignments = { Draggodeidad: 0, JulianDele: 0, osbaldoXxC: 0 };
for (const issue of planData.plan.issues) assignments[issue.assignee] += 1;
return [{
  json: {
    ...planData,
    verifiedIssues: planData.planKeys.map((key) => ({ key, number: byKey[key].number, title: byKey[key].title })),
    assignments,
    assignmentLoads: planData.assignmentPolicy?.loads || null,
    verified: true,
  },
}];

const data = $json;
const issueLines = data.verifiedIssues.map((issue) => `${issue.key}: #${issue.number} ${issue.title}`).join('
');
return [{
  json: {
    ...data,
    notificationSubject: `✅ ${data.course} Semana ${data.weekPadded} procesada`,
    notificationBody: `✅ ${data.course} W${data.weekPadded} procesada

CourseWork: ${data.plan.assignmentTitle}
CourseWork ID: ${data.courseWorkId}
Starter: ${data.starter?.name || 'sin ZIP'}
Repositorio: ${data.repository}
Deadline: ${data.plan.deadline || 'No indicada'}

Issues verificadas: ${data.verifiedIssues.length}

Draggodeidad: ${data.assignments.Draggodeidad} Issues; carga funcional ${data.assignmentLoads?.Draggodeidad?.functional ?? 'n/a'}
JulianDele: ${data.assignments.JulianDele} Issues; carga funcional ${data.assignmentLoads?.JulianDele?.functional ?? 'n/a'}
osbaldoXxC: ${data.assignments.osbaldoXxC} Issues; carga funcional ${data.assignmentLoads?.osbaldoXxC?.functional ?? 'n/a'}

${issueLines}`,
  },
}];
